<?php $e = static fn (mixed $v): string => htmlspecialchars((string) $v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); ?>
<section class="content-container"><h1>Dokumenty po terminie przeglądu</h1><p>Lista obejmuje dostępne opublikowane dokumenty. Przegląd potwierdza aktualność konkretnej opublikowanej rewizji.</p><div class="card panel table-scroll"><table><thead><tr><th>Dokument</th><th>Właściciel merytoryczny</th><th>Termin przeglądu</th></tr></thead><tbody><?php foreach ($pages as $page): ?><tr><td><a href="/spaces/<?= rawurlencode($page['space_key']) ?>/pages/<?= rawurlencode($page['slug']) ?>"><?= $e($page['title']) ?></a></td><td><?= $e($page['content_owner'] ?? 'Nieaktywne konto') ?></td><td><?= $e($page['review_due_at']) ?></td></tr><?php endforeach; ?><?php if ($pages === []): ?><tr><td colspan="3">Brak dokumentów po terminie przeglądu.</td></tr><?php endif; ?></tbody></table></div></section>
